import unittest
from datetime import date

class SmokeTests(unittest.TestCase):
    def test_aggregate_stock(self):
        from inventory import aggregate_stock as core
        self.assertEqual(core.aggregate_stock([("A",2),("B",3)]),{"A":2,"B":3})

    def test_aggregate_stock_ordinary_0(self):
        from inventory import aggregate_stock as core
        self.assertEqual(core.aggregate_stock([]),{})

    def test_reorder_inclusive(self):
        from inventory import reorder_inclusive as core
        from inventory import reorder_inclusive_api as api
        self.assertEqual(api.reorder_skus([("A",1,2),("B",4,2)]),["A"])

    def test_reorder_inclusive_ordinary_0(self):
        from inventory import reorder_inclusive as core
        from inventory import reorder_inclusive_api as api
        self.assertFalse(core.reorder_needed(8,2))

    def test_pack_ceiling(self):
        from inventory import pack_ceiling as core
        self.assertEqual(core.packs_required(12,6),2)

    def test_pack_ceiling_ordinary_0(self):
        from inventory import pack_ceiling as core
        self.assertEqual(core.packs_required(0,4),0)
